import{d as u,C as t,o as c,c as b,j as a,a as o,E as r,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const w=JSON.parse('{"title":"道德经第四十八章","description":"比较为学日益与为道日损，理解返虚、无为及无事取天下。","frontmatter":{"title":"道德经第四十八章","description":"比较为学日益与为道日损，理解返虚、无为及无事取天下。","category":"guide","aliases":["道德经第四十八章","老子第四十八章","dao de jing chapter 48"],"source":["王弼《道德真经注》卷三"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-48.md","filePath":"daoism/dao-de-jing/chapter-48.md","lastUpdated":1794189804000}'),p={name:"daoism/dao-de-jing/chapter-48.md"},_=u({...p,setup(x){const n=[{id:"learning-and-dao",label:"为学日益，为道日损",showLabel:!0,sentences:[[{text:"为学",glossary:"weixue"},"日益，",{text:"为道",glossary:"weidao"},"日",{text:"损",glossary:"sun"},"。"]],note:["【白话】从事学问，所知所能日益增加；行道的工夫，则朝着日益减损的方向。二者所指的工夫不同，不能只用增加多少来衡量。","【王弼注择要】为学下注「务欲进其所能，益其所习」；为道下注「务欲反虚无也」，以增加能力、习得与返于虚无作对照。","【读法】依返虚读日损，可从减去执定与刻意造作来理解，不是删去已经学会的知识和能力。所据录文此处作曰损，本站保留日损，差异在篇末列明。"]},{id:"repeated-reduction",label:"损之又损",showLabel:!0,sentences:[[{text:"损",glossary:"sun"},"之又",{text:"损",glossary:"sun"},"，以至于",{text:"无为",glossary:"wuwei"},"。"]],note:["【白话】继续减损，再继续减损，直到不再以自己的私意妄加造作。减损指向无为，而非以少为终点。","【读法】所据录文此句未另见独立王注，可连上一段返虚之注与下一段无为之用理解。每次所损为何，应放回是否执定一形、妨碍事物成全来判断。","【读法】损之又损不是对资源、知识、责任一概减到没有；若减去的是事情成立的必要条件，便不能只凭变少自称合道。"]},{id:"nonaction-and-completion",label:"无为而无不为",showLabel:!0,sentences:[[{text:"无为",glossary:"wuwei"},"而",{text:"无不为",glossary:"wubuwei"},"。"]],note:["【白话】不妄作，却使事物无不得到成就。这里的无不为承接无为的作用，不等于自己必须亲手做完所有事情。","【王弼注择要】「有为则有所失，故无为乃无所不为也。」注从强作可能有所偏失，说明不固执己意才不致遗漏成物的可能。","【读法】这与第三十七章呼应。无不为是章内成用的表达，不是宣称无需条件即可获得任何结果；仍须辨明哪些行动顺应事情的实际需要。"]},{id:"governing-without-invented-interference",label:"取天下常以无事",showLabel:!0,sentences:[[{text:"取",glossary:"qu"},"天下常以",{text:"无事",glossary:"wushi"},"，及其",{text:"有事",glossary:"youshi"},"，不足以",{text:"取",glossary:"qu"},"天下。"]],note:["【白话】治理、持守天下，常要以不妄造事端为原则；等到只凭自己不断造事，便不足以治理天下了。","【王弼注择要】无事下注「动常因也」；有事下注「自已造也」；不足以取天下下注「失统本也」。本页保留第二处录文的自已字样，不擅改后当作原引。","【读法】取天下在这里落到治理与持守，王弼以能否统本说明。无事、有事重在因物与自造的分别，不按事务数量判断，也不取消日常维护、应急和照料。"]}],s=[{id:"weixue",term:"为学",sense:1},{id:"weidao",term:"为道",sense:1},{id:"sun",term:"损",sense:1},{id:"wuwei",term:"无为",sense:1},{id:"wubuwei",term:"无不为",sense:1},{id:"qu",term:"取",sense:1},{id:"wushi",term:"无事",sense:1},{id:"youshi",term:"有事",sense:1}];return(g,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return c(),b("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第四十八章",tabindex:"-1"},[o("道德经第四十八章 "),a("a",{class:"header-anchor",href:"#道德经第四十八章","aria-label":'Permalink to "道德经第四十八章"'},"​")],-1)),r(i,{title:"为学在增加，为道为什么反而要减损",summary:"本章先比较为学与为道，再把日损推进到无为，最后落到取天下的无事与有事。王弼以增进所能、返于虚无解释益损，以因物与自造解释无事、有事，重点在成用而非一味减少。",points:[{label:"先读",text:"为学之益写所能所习的增加，为道之损写返虚的方向，不能混成停止学习。"},{label:"再辨",text:"无为与无不为相连，不是个人必须包办一切，也不是所有事情都任其自流。"},{label:"后看",text:"无事循动常因解释，有事循自己造作解释，不按忙闲多少判断。"}],hint:"为学、为道的为读 wéi；损为减损，无事在这里是少造事端、因物而行，不是无人需要照料。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[o("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),r(l,{sections:n,glossary:s}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[o("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"为学日益，为道日损。",tone:"两种工夫的方向",guide:"增进所能所习与返于虚无各有所指，不能只比较数量。"},{text:"损之又损，以至于无为。无为而无不为。",tone:"减损须指向成用",guide:"损去妄作而让事物成就，不以少做、少知本身为目标。"},{text:"取天下常以无事，及其有事，不足以取天下。",tone:"因物还是自造",guide:"以动常因与自己造作的分别读无事、有事，落到治理的根本。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[o("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),r(h,{items:s}),e[4]||(e[4]=m("",15))])}}});export{w as __pageData,_ as default};
